{"connection_id":"BC-3bea90865b5753d2687c","ref":"WLC:Job.39.8","status":"accepted","reason":"The wild ass ranges mountains for pasture, showing a free grazing pattern outside the owned herd.","paragraphs":[52],"evidence":["WLC:Job.39.5","WLC:Job.39.6","WLC:Job.39.8","WLC:Job.39.9"],"annotations":["S001-TEV-MTF-002"]}
{"connection_id":"BC-70e3613dd13fd491ae94","ref":"WLC:Job.39.9","status":"accepted","reason":"The wild ox will not serve a human or stay at his manger, the precise counterpoint to the tamed domestic animal.","paragraphs":[52],"evidence":["WLC:Job.39.5","WLC:Job.39.6","WLC:Job.39.8","WLC:Job.39.9"],"annotations":["S001-TEV-MTF-002"]}
{"connection_id":"BC-12b66730f06da9719f1a","ref":"WLC:Job.39.9","status":"accepted","reason":"Refusal of service and manger stay are both in the Hebrew verse and in the domesticated/wild comparison.","paragraphs":[52],"evidence":["WLC:Job.39.5","WLC:Job.39.6","WLC:Job.39.8","WLC:Job.39.9"],"annotations":["S001-TEV-MTF-002"]}
